        "type": "string",
        "description": "当前前方等待桌数",
        "sampleValue": "32"
      },
      "unit": {
        "type": "string",
        "description": "等待桌数单位",
        "sampleValue": "桌"
      },
      "actionTip": {
        "type": "string",
        "description": "进入应用前的简短提示",
        "sampleValue": "查看进度"
      },
      "actionLabel": {
        "type": "string",
        "description": "进入应用的动作标签",
        "sampleValue": "进App"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/hourglass_fill.svg",
      "description": "沙漏和齿轮组合图标，适合表达等待、排队或处理中状态。"
    }
  ]
}

